+void OpenXRSpatialEntityTracker::set_spatial_tracking_state(const OpenXrSpatialEntityTrackingState p_state) {
+	if (spatial_tracking_state != p_state) {
+		spatial_tracking_state = p_state;
+
+		emit_signal(SNAME("spatial_tracking_state_changed"), spatial_tracking_state);
+	}
+}
+
+OpenXRSpatialEntityTracker::OpenXrSpatialEntityTrackingState OpenXRSpatialEntityTracker::get_spatial_tracking_state() const {
