+		// We want updates for all anchors
+		Vector<RID> entities;
+		entities.resize(anchors.size());
+		RID *entity = entities.ptrw();
+		for (const KeyValue<XrSpatialEntityIdEXT, Ref<OpenXRAnchorTracker>> &e : anchors) {
