+OpenXRSpatialComponentMarkerList::OpenXRMarkerType OpenXRSpatialComponentMarkerList::get_marker_type(int64_t p_index) const {
+	ERR_FAIL_INDEX_V(p_index, marker_data.size(), OPENXR_MARKER_TYPE_UNKNOWN);
+
+	// We can't simply cast these.
+	// This may give us problems in the future if we get new types through vendor extensions.
+	switch (marker_data[p_index].capability) {
+		case XR_SPATIAL_CAPABILITY_MARKER_TRACKING_QR_CODE_EXT: {
+			return OPENXR_MARKER_TYPE_QRCODE;
+		} break;
+		case XR_SPATIAL_CAPABILITY_MARKER_TRACKING_MICRO_QR_CODE_EXT: {
+			return OPENXR_MARKER_TYPE_MICRO_QRCODE;
+		} break;
+		case XR_SPATIAL_CAPABILITY_MARKER_TRACKING_ARUCO_MARKER_EXT: {
+			return OPENXR_MARKER_TYPE_ARUCO;
+		} break;
+		case XR_SPATIAL_CAPABILITY_MARKER_TRACKING_APRIL_TAG_EXT: {
+			return OPENXR_MARKER_TYPE_APRIL_TAG;
+		} break;
+		default: {
+			return OPENXR_MARKER_TYPE_UNKNOWN;
+		} break;
+	}
+}
