+				set_tracker_desc("Wall plane");
+			} break;
+			case OpenXRSpatialComponentPlaneSemanticLabelList::OpenXrSpatialPlaneSemanticLabel::OPENXR_SPATIAL_PLANE_SEMANTIC_LABEL_CEILING: {
+				set_tracker_desc("Ceiling plane");
+			} break;
+			case OpenXRSpatialComponentPlaneSemanticLabelList::OpenXrSpatialPlaneSemanticLabel::OPENXR_SPATIAL_PLANE_SEMANTIC_LABEL_TABLE: {
