+
+		// Reference frame will already be applied to pose used on our XRNode3D but we do need to apply our scale
+		XRServer *xr_server = XRServer::get_singleton();
+		if (xr_server) {
+			offset.origin *= xr_server->get_world_scale();
+		}
+	}
+
+	return offset;
+}
