+bool OpenXRSpatialCapabilityConfigurationAnchor::has_valid_configuration() const {
+	OpenXRSpatialAnchorCapability *capability = OpenXRSpatialAnchorCapability::get_singleton();
+	ERR_FAIL_NULL_V(capability, false);
