+	OpenXRSpatialEntityExtension *se_extension = OpenXRSpatialEntityExtension::get_singleton();
+	ERR_FAIL_NULL(se_extension);
+
+	if (spatial_anchor_ext) {
+		EXT_INIT_XR_FUNC(xrCreateSpatialAnchorEXT);
