+	tracker.instantiate();
+	tracker->set_entity(se_extension->add_spatial_entity(sc, entity_id, entity));
+	tracker->set_tracker_desc("Anchor");
+	tracker->set_pose(SNAME("default"), p_transform, Vector3(), Vector3());
