+bool OpenXRSpatialAnchorCapability::is_spatial_persistence_supported() {
+	// Need anchor support for persistence to be usable
+	if (!is_spatial_anchor_supported()) {
+		return false;
+	}
+
+	return spatial_persistence_ext;
+}
