+
+				char32_t c = p_uuid[j++];
+				if (c >= '0' && c <= '9') {
+					val += uint8_t(c - '0');
+				} else if (c >= 'a' && c <= 'f') {
+					val += uint8_t(10 + c - 'a');
+				} else if (c >= 'A' && c <= 'F') {
+					val += uint8_t(10 + c - 'A');
+				} else {
+					WARN_PRINT("OpenXR : unexpected character in UUID: " + String::num_int64(c));
+				}
+			}
+		}
+
+		new_uuid.data[i] = val;
+	}
+
+	set_uuid(new_uuid);
+}
+
+bool OpenXRAnchorTracker::uuid_is_equal(const XrUuid &p_a, const XrUuid &p_b) {
+	for (int i = 0; i < XR_UUID_SIZE; i++) {
+		if (p_a.data[i] != p_b.data[i]) {
+			return false;
+		}
+	}
+
+	return true;
+}
