+////////////////////////////////////////////////////////////////////////////
+// Discovery queries
+
+Ref<OpenXRFutureResult> OpenXRSpatialEntityExtension::discover_spatial_entities(RID p_spatial_context, const Vector<XrSpatialComponentTypeEXT> &p_component_types, Ref<OpenXRStructureBase> p_next, Callable p_user_callback) {
+	if (!get_active()) {
+		return nullptr;
+	}
+
+	OpenXRAPI *openxr_api = OpenXRAPI::get_singleton();
+	ERR_FAIL_NULL_V(openxr_api, nullptr);
+
+	OpenXRFutureExtension *future_api = OpenXRFutureExtension::get_singleton();
+	ERR_FAIL_NULL_V(future_api, nullptr);
+
+	void *next = nullptr;
+	if (p_next.is_valid()) {
+		next = p_next->get_header(next);
+	}
+
+	// Start our discovery snapshot.
