+
+		char a = (uuid.data[i] & 0xF0) >> 4;
+		char b = uuid.data[i] & 0x0F;
+
+		if (a < 10) {
+			ret += '0' + a;
+		} else {
+			ret += 'a' + a - 10;
+		}
+
+		if (b < 10) {
+			ret += '0' + b;
+		} else {
+			ret += 'a' + b - 10;
